<?php
function h(?string $v):string{return htmlspecialchars($v??'',ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function csrf_token():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}
function verify_csrf():void{if($_SERVER['REQUEST_METHOD']==='POST'&&!hash_equals(csrf_token(),(string)($_POST['csrf']??''))){http_response_code(419);exit('Invalid form token. Reload and try again.');}}
function require_login():void{if(empty($_SESSION['user_id'])){header('Location: login.php');exit;}}
function require_role(array $roles):void{require_login();if(!in_array($_SESSION['role']??'', $roles,true)){http_response_code(403);exit('Access denied.');}}
function audit(mysqli $db,string $action,?string $type=null,?string $id=null,string $details=''):void{$uid=$_SESSION['user_id']??null;$un=$_SESSION['username']??'system';$ip=substr((string)($_SERVER['REMOTE_ADDR']??''),0,45);$s=$db->prepare('INSERT INTO audit_logs(user_id,username,action,entity_type,entity_id,details,ip_address) VALUES(?,?,?,?,?,?,?)');$s->bind_param('issssss',$uid,$un,$action,$type,$id,$details,$ip);$s->execute();}
function page_header(string $title):void{echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.h($title).' - HR Records</title><style>
*{box-sizing:border-box}body{margin:0;font:15px/1.5 system-ui,Arial;background:#f3f6fa;color:#172334}header{background:#17324d;color:white;padding:15px 4%;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}header a{color:white;text-decoration:none;margin-right:12px}.container{max-width:1180px;margin:28px auto;padding:0 18px}.card{background:white;border:1px solid #dce3ec;border-radius:12px;padding:20px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:16px}.stat{font-size:28px;font-weight:750;color:#17324d}label{display:block;font-weight:650;margin:12px 0 5px}input,select,textarea{width:100%;padding:10px;border:1px solid #bdc8d6;border-radius:7px;font:inherit}textarea{min-height:80px}button,.btn{display:inline-block;border:0;border-radius:7px;padding:9px 14px;background:#2563eb;color:white;text-decoration:none;cursor:pointer;font:inherit}.muted-btn{background:#52657a}.danger{background:#b42318}.actions{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #dce3ec;vertical-align:top}th{background:#eef3f8}.table-wrap{overflow-x:auto}.notice{padding:12px;border-radius:8px;background:#eaf5ee;margin:12px 0}.error{background:#fff0ef}.muted{color:#617084}.form-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}footer{text-align:center;color:#6b7788;padding:24px}@media print{header,.no-print,footer{display:none!important}body{background:white}.container{max-width:none;margin:0;padding:0}.card{border:0}}
</style></head><body><header><strong>HR & Employee Records</strong><nav>';
if(!empty($_SESSION['user_id'])){echo '<a href="index.php">Dashboard</a><a href="employees.php">Employees</a><a href="reports.php">Reports</a>';if(($_SESSION['role']??'')==='admin')echo '<a href="audit_logs.php">Audit Logs</a><a href="backup.php">Backup</a>';echo h($_SESSION['full_name']??'').' <a href="logout.php">Logout</a>';}
echo '</nav></header><main class="container">';}
function page_footer():void{echo '</main><footer>HR & Employee Records System · PHP + MySQL</footer></body></html>';}
function flash(string $m,bool $err=false):void{$_SESSION['flash']=[$m,$err];}
function show_flash():void{if(!empty($_SESSION['flash'])){[$m,$e]=$_SESSION['flash'];unset($_SESSION['flash']);echo '<div class="notice '.($e?'error':'').'">'.h($m).'</div>';}}
function upload_file(string $key,string $kind):?string{if(empty($_FILES[$key])||$_FILES[$key]['error']===UPLOAD_ERR_NO_FILE)return null;$f=$_FILES[$key];if($f['error']!==UPLOAD_ERR_OK||$f['size']>5242880)throw new RuntimeException('Upload failed or file exceeds 5 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$types=$kind==='photo'?['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp']:['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png'];if(!isset($types[$mime]))throw new RuntimeException('Unsupported file type. Photo: JPG/PNG/WEBP. Document: PDF/JPG/PNG.');$dir=__DIR__.'/uploads';if(!is_dir($dir))mkdir($dir,0750,true);$name=$kind.'_'.bin2hex(random_bytes(16)).'.'.$types[$mime];if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Could not save uploaded file.');return 'uploads/'.$name;}